function AgentLoop(task):
  plan = Planner(task)
  while not goal_achieved:
    action = Executor(plan)
    result = Environment.execute(action)
    feedback = Reviewer(result, plan)
    if feedback.is_rejected:
      plan = Planner(task, feedback)
    else:
      plan.update(result)

