class Agent:
    def run(objective):
        plan = Planner.create(objective)
        is_finished = False
        while not is_finished:
            for step in plan:
                output = Executor.execute(step)
                feedback = Reviewer.evaluate(output, objective)
                if feedback.needs_replan:
                    plan = Planner.refine(plan, feedback)
                    break
                if feedback.is_complete:
                    is_finished = True

module Planner:
    def create(objective): return decompose(objective)
    def refine(plan, feedback): return update_plan(plan, feedback)

module Executor:
    def execute(step): return run_tool(step)

module Reviewer:
    def evaluate(output, objective): return validate(output, objective)

